         )',
        v_table
    ) USING p_month, p_year, p_rto_code, p_rto_name, p_rows;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    EXECUTE format(
        'SELECT coalesce(sum("Total"), 0) FROM %I
         WHERE "year" = $1 AND "month" = $2 AND "rto_code" = $3',
        v_table
    ) INTO v_units USING p_year, p_month, p_rto_code;

    EXECUTE format(
        'SELECT coalesce(jsonb_agg(jsonb_build_object(
                ''maker'', "Maker", ''total'', "Total", ''summed'', summed
            )), ''[]''::jsonb)
         FROM (
             SELECT t."Maker", t."Total", (coalesce(t."Three Wheeler (Goods)", 0) + coalesce(t."Three Wheeler (Passenger)", 0) + coalesce(t."e-Rickshaw with Cart (G)", 0) + coalesce(t."e-Rickshaw(P)", 0) + coalesce(t."Tractor-Trolley(Commercial)", 0) + coalesce(t."Trailer (Agricultural)", 0) + coalesce(t."Harvester", 0) + coalesce(t."Goods Carrier", 0) + coalesce(t."M-Cycle/Scooter", 0) + coalesce(t."Trailer (Commercial)", 0) + coalesce(t."Construction Equipment Vehicle", 0) + coalesce(t."Crane Mounted Vehicle", 0) + coalesce(t."Agricultural Tractor", 0) + coalesce(t."Construction Equipment Vehicle (Commercial)", 0) + coalesce(t."Earth Moving Equipment", 0) + coalesce(t."Excavator (Commercial)", 0) + coalesce(t."Excavator (NT)", 0) + coalesce(t."Fork Lift", 0) + coalesce(t."Road Roller", 0) + coalesce(t."Tractor (Commercial)", 0) + coalesce(t."Motorised Cycle (CC  25cc)", 0) + coalesce(t."Bus", 0) + coalesce(t."Semi-Trailer (Commercial)", 0) + coalesce(t."Motor Car", 0) + coalesce(t."Vehicle Fitted With Rig", 0) + coalesce(t."Moped", 0) + coalesce(t."Armoured/Specialised Vehicle", 0) + coalesce(t."Ambulance", 0) + coalesce(t."Animal Ambulance", 0) + coalesce(t."Articulated Vehicle", 0) + coalesce(t."Auxiliary Trailer", 0) + coalesce(t."Camper Van / Trailer", 0) + coalesce(t."Camper Van / Trailer (Private Use)", 0) + coalesce(t."Dumper", 0) + coalesce(t."Educational Institution Bus", 0) + coalesce(t."Fire Fighting Vehicle", 0) + coalesce(t."Fire Tenders", 0) + coalesce(t."Hearses", 0) + coalesce(t."Maxi Cab", 0) + coalesce(t."Mobile Canteen", 0) + coalesce(t."Mobile Clinic", 0) + coalesce(t."Mobile Workshop", 0) + coalesce(t."Omni Bus", 0) + coalesce(t."Private Service Vehicle", 0) + coalesce(t."Private Service Vehicle (Individual Use)", 0) + coalesce(t."Puller Tractor", 0) + coalesce(t."Recovery Vehicle", 0) + coalesce(t."School Bus", 0) + coalesce(t."Snorked Ladders", 0) + coalesce(t."Tow Truck", 0) + coalesce(t."Tower Wagon", 0) + coalesce(t."Tree Trimming Vehicle", 0) + coalesce(t."Vehicle Fitted With Compressor", 0) + coalesce(t."Vehicle Fitted With Generator", 0) + coalesce(t."X-Ray Van", 0) + coalesce(t."Adapted Vehicle", 0) + coalesce(t."M-Cycle/Scooter-With Side Car", 0) + coalesce(t."Motor Cycle/Scooter-Used For Hire", 0) + coalesce(t."Three Wheeler (Personal)", 0) + coalesce(t."Motor Cab", 0) + coalesce(t."Motor Cycle/Scooter-SideCar(T)", 0) + coalesce(t."Quadricycle (Commercial)", 0) + coalesce(t."Quadricycle (Private)", 0) + coalesce(t."Luxury Cab", 0) + coalesce(t."Breakdown Van", 0) + coalesce(t."Cash Van", 0) + coalesce(t."Library Van", 0) + coalesce(t."Omni Bus (Private Use)", 0) + coalesce(t."Vintage Motor Vehicle", 0) + coalesce(t."Trailer For Personal Use", 0) + coalesce(t."Motor Caravan", 0) + coalesce(t."Power Tiller", 0) + coalesce(t."Modular Hydraulic Trailer", 0) + coalesce(t."Bulldozer", 0) + coalesce(t."Motor Cycle/Scooter-With Trailer", 0) + coalesce(t."Power Tiller (Commercial)", 0)) AS summed
             FROM %I AS t
             WHERE t."year" = $1 AND t."month" = $2 AND t."rto_code" = $3
         ) s
         WHERE s."Total" IS DISTINCT FROM s.summed',
        v_table
    ) INTO v_mismatches USING p_year, p_month, p_rto_code;

    RETURN jsonb_build_object(
        'table', v_table,
        'rto_code', p_rto_code,
        'rto_name', p_rto_name,
        'month', p_month,
        'year', p_year,
        'deleted', v_deleted,
        'inserted', v_inserted,
        'units', v_units,
        'mismatches', v_mismatches
    );
END;
$$;

REVOKE ALL ON FUNCTION public.import_rto_month(text, text, text, text, integer, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.import_rto_month(text, text, text, text, integer, jsonb) FROM anon, authenticated;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
        GRANT EXECUTE ON FUNCTION public.import_rto_month(text, text, text, text, integer, jsonb)
            TO service_role;
    END IF;
END;
$$;

